use anyhow::{Context, Result, bail};
use clap::Args;
use std::{
    fs,
    path::{Path, PathBuf},
};

#[derive(Args)]
pub struct Options {
    #[arg(long)]
    target: String,
    /// Actual Player executable reported by Cargo's compiler-artifact message.
    #[arg(long)]
    binary: PathBuf,
    /// Flat Player resources generated by `roukaku package bundle`.
    #[arg(long)]
    resources: PathBuf,
    #[arg(long)]
    version: String,
    #[arg(long)]
    out: PathBuf,
}

fn reject_link(path: &Path) -> Result<()> {
    let metadata = fs::symlink_metadata(path)?;
    if metadata.file_type().is_symlink() {
        bail!("Apple package input is a link: {}", path.display());
    }
    #[cfg(windows)]
    {
        use std::os::windows::fs::MetadataExt;
        if metadata.file_attributes() & 0x400 != 0 {
            bail!("Apple package input is a reparse point: {}", path.display());
        }
    }
    Ok(())
}

fn reject_overlap(resources: &Path, binary: &Path, out: &Path) -> Result<()> {
    let absolute = std::path::absolute(out)?;
    if absolute
        .components()
        .any(|part| part == std::path::Component::ParentDir)
    {
        bail!("Apple package output cannot contain parent traversal");
    }
    let mut existing = absolute.as_path();
    while !existing.exists() {
        existing = existing
            .parent()
            .context("output has no existing ancestor")?;
    }
    let resolved = existing
        .canonicalize()?
        .join(absolute.strip_prefix(existing)?);
    if resolved.starts_with(resources)
        || resources.starts_with(&resolved)
        || binary.starts_with(&resolved)
    {
        bail!("Apple package output overlaps its inputs");
    }
    Ok(())
}

pub fn run(root: &Path, options: &Options) -> Result<()> {
    if !crate::apple::supported(&options.target) {
        bail!("unsupported Apple target");
    }
    semver::Version::parse(&options.version)?;
    reject_link(&options.resources)?;
    reject_link(&options.binary)?;
    let resources = options.resources.canonicalize()?;
    let binary = options.binary.canonicalize()?;
    reject_overlap(&resources, &binary, &options.out)?;
    if !resources.join("RoukakuPlayer.config.json").is_file() {
        bail!("resources must contain a real Player config and its bundled package");
    }
    let config: serde_json::Value =
        serde_json::from_slice(&fs::read(resources.join("RoukakuPlayer.config.json"))?)?;
    let platform = if options.target.contains("-ios") {
        "ios"
    } else {
        "macos"
    };
    if config["schema"] != "roukaku.player_config.v2" || config["platform"] != platform {
        bail!("Player config does not match {}", options.target);
    }
    crate::util::new_output(&options.out)?;
    let result = (|| {
        let temp = tempfile::tempdir_in(&options.out)?;
        let flat = temp.path().join("flat");
        fs::create_dir(&flat)?;
        crate::util::copy(&binary, &flat.join("roukaku-player"))?;
        let mut seen = std::collections::BTreeSet::new();
        for entry in walkdir::WalkDir::new(&resources).follow_links(false) {
            let entry = entry?;
            reject_link(entry.path())?;
            let relative = entry.path().strip_prefix(&resources)?;
            if relative.as_os_str().is_empty() {
                continue;
            }
            if !seen.insert(
                relative
                    .to_str()
                    .context("non UTF-8 Apple resource path")?
                    .to_lowercase(),
            ) {
                bail!(
                    "case-insensitive Apple resource path collision: {}",
                    relative.display()
                );
            }
            if relative == Path::new("roukaku-player") {
                if crate::util::hash(entry.path())? != crate::util::hash(&binary)? {
                    bail!("resource tree contains a different Player executable");
                }
                continue;
            }
            let destination = flat.join(relative);
            if entry.file_type().is_dir() {
                fs::create_dir_all(destination)?;
            } else {
                if let Some(parent) = destination.parent() {
                    fs::create_dir_all(parent)?;
                }
                crate::util::copy(entry.path(), &destination)?;
            }
        }
        let licenses = flat.join("licenses/roukaku");
        fs::create_dir_all(&licenses)?;
        for name in ["LICENSE-MIT", "LICENSE-APACHE", "ORIGINS.md"] {
            crate::util::copy(&root.join(name), &licenses.join(name))?;
        }
        let native = native_share(root, &options.target)?;
        for entry in walkdir::WalkDir::new(&native).follow_links(false) {
            let entry = entry?;
            if entry.file_name() == "copyright" && entry.file_type().is_file() {
                let port = entry
                    .path()
                    .parent()
                    .and_then(Path::file_name)
                    .context("native dependency license owner")?;
                let destination = flat.join("licenses/native").join(port);
                fs::create_dir_all(&destination)?;
                crate::util::copy(entry.path(), &destination.join("copyright"))?;
            }
        }
        let app = crate::apple::bundle(
            &flat,
            &options.target,
            "roukaku-player",
            "RoukakuPlayer",
            "org.shinkirou.roukakuplayer",
            &options.version,
        )?;
        let device = options.target == "aarch64-apple-ios";
        let archive = options.out.join(format!(
            "RoukakuPlayer-{}-{}-{}.{}",
            options.version,
            options.target,
            if device {
                "adhoc-device-test"
            } else if options.target.contains("-ios") {
                "simulator-test"
            } else {
                "adhoc"
            },
            if device { "ipa" } else { "zip" }
        ));
        if device {
            let payload = temp.path().join("Payload");
            fs::create_dir(&payload)?;
            fs::rename(&app, payload.join(app.file_name().context("app filename")?))?;
            fs::remove_dir(&flat)?;
            crate::release::archive(temp.path(), &archive)?;
            fs::rename(payload, options.out.join("Payload"))?;
        } else {
            crate::release::archive(&flat, &archive)?;
            fs::rename(
                &app,
                options.out.join(app.file_name().context("app filename")?),
            )?;
        }
        println!("{}", archive.display());
        Ok(())
    })();
    if result.is_err() {
        fs::remove_dir_all(&options.out).context("removing failed Apple package staging")?;
    }
    result
}
pub fn native_share(root: &Path, target: &str) -> Result<PathBuf> {
    let share = if crate::apple::cross_host(target) {
        root.join(".work/apple-native").join(target).join("share")
    } else {
        let native = std::env::var_os("ROUKAKU_SUBTITLE_VCPKG_ROOT")
            .map(PathBuf::from)
            .unwrap_or_else(|| root.join(".work/vcpkg-subtitle"));
        native
            .join("installed")
            .join(if target.starts_with("aarch64") {
                "arm64-osx"
            } else {
                "x64-osx"
            })
            .join("share")
    };
    if !share.join("libass/copyright").is_file() {
        bail!(
            "Apple subtitle dependency licenses missing at {}; prepare native deps or apple-image first",
            share.display()
        );
    }
    Ok(share)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn output_cannot_be_created_inside_resources() {
        let temp = tempfile::tempdir().unwrap();
        let resources = temp.path().join("resources");
        fs::create_dir(&resources).unwrap();
        let binary = temp.path().join("player");
        fs::write(&binary, b"source").unwrap();
        let output = resources.join("nested/package");
        assert!(
            reject_overlap(
                &resources.canonicalize().unwrap(),
                &binary.canonicalize().unwrap(),
                &output
            )
            .is_err()
        );
        assert!(!resources.join("nested").exists());
        assert_eq!(fs::read(binary).unwrap(), b"source");
    }
}
